//! Transactions that cannot call out to the network (platform 4.3).
//!
//! [`tx!`](crate::tx!) is the only way to run a transaction through this crate:
//! - its closure gets a [`Tx`], whose API awaits nothing but the database, and the macro denies clippy's
//!   `disallowed_methods` inside the closure. CI's second clippy pass (`CLIPPY_CONF_DIR=target/tx-rule`, generated by `aviary_source_rules::tx_rule`,
//!   `-A clippy::disallowed_methods` everywhere else) lists the network calls: `reqwest`'s, the contract crates'
//!   typed clients, `aviary_core::http::send`, the Kubernetes API, `hyper` and `tokio` sockets, and every AWS SDK
//!   operation (S3 and EC2). A call made in a helper function that the closure calls is not seen.
//! - the other ways into a transaction are refused: [`crate::Pool::get`] hands out a [`crate::Conn`] that refuses
//!   `begin`/`commit`/`savepoint` and has no `transaction()`, the deadpool pool itself is not public
//!   ([`crate::Pool::status`] gives its figures); the repository's `clippy.toml` disallows
//!   `tokio-postgres`' and deadpool's `transaction()`/`build_transaction()` and calling `aviary_pg::__run_tx`
//!   directly (the macro allows it for its own call).
//!
//! The role's `idle_in_transaction_session_timeout = 60s` (platform 11.1) is only a backstop.

use std::future::Future;
use std::marker::PhantomData;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};

use deadpool_postgres::Object;

use tokio_postgres::error::SqlState;
use tokio_postgres::types::ToSql;
use tokio_postgres::Row;

use crate::stmt::{self, StmtGuard, statement};
use crate::{Error, Pool};

/// The future a [`tx!`](crate::tx!) closure returns.
pub type TxFuture<'a, T, E> = Pin<Box<dyn Future<Output = Result<T, E>> + Send + 'a>>;

/// One open transaction on a pooled connection it owns. Statements are prepared once per connection and cached
/// (a stale cached statement is handled as `crate::stmt` describes).
///
/// `'env` is the caller's scope: the closure's future may borrow anything that outlives it. A `Tx` dropped before
/// its commit or rollback (the future was cancelled at any point from `begin` on, or panicked) takes its connection
/// out of the pool and closes it, so the server rolls the transaction back and no pooled connection is ever left
/// inside one. (The pool's recycle check refuses such a connection too, as a backstop.)
///
/// A statement that fails aborts the transaction in Postgres even when the closure ignores the error; `COMMIT` then
/// rolls back without an error. So whenever a statement failed or was cancelled, [`tx!`](crate::tx!) checks the
/// transaction before committing and answers [`Error::RolledBack`] when it is aborted (a savepoint the closure rolled
/// back to recovers it, and then the commit goes ahead).
pub struct Tx<'env> {
    client: Option<Object>,
    pool: deadpool_postgres::Pool,
    /// Statements started so far.
    started: AtomicU32,
    /// A statement failed or was cancelled: the transaction may be aborted.
    doubt: AtomicBool,
    /// The connection was lost (the database away for a moment): [`__run_tx`] runs the closure again.
    lost: AtomicBool,
    _env: PhantomData<&'env ()>,
}

impl std::fmt::Debug for Tx<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Tx").finish_non_exhaustive()
    }
}

impl Drop for Tx<'_> {
    fn drop(&mut self) {
        if let Some(obj) = self.client.take() {
            // still inside the transaction: never hand this connection back
            drop(Object::take(obj));
        }
    }
}

impl Tx<'_> {
    fn client(&self) -> Result<&Object, Error> {
        self.client.as_ref().ok_or(Error::Closed)
    }

    #[allow(clippy::unused_async, clippy::unused_async_trait_impl)] // the shape `statement!` expects (Conn's awaits)
    async fn stmt_client(&self) -> Result<&Object, Error> {
        self.client()
    }

    /// Notes a lost connection, so the whole transaction runs again ([`crate::retry`]).
    fn note(&self, e: &tokio_postgres::Error) {
        if crate::error::transient_db(e) {
            self.lost.store(true, Ordering::SeqCst);
        }
    }

    fn guard(&self, sql: &str) -> Result<StmtGuard<'_>, Error> {
        stmt::refuse_control(sql, true)?;
        let first = self.started.fetch_add(1, Ordering::SeqCst) == 0;
        Ok(StmtGuard::new(&self.doubt, first))
    }

    /// On a stale cached statement: clear the pool's caches; when nothing else ran in this transaction, restart it
    /// and retry once (`Ok`). Otherwise the statement's error.
    async fn recover(&self, g: &mut StmtGuard<'_>, e: tokio_postgres::Error) -> Result<(), Error> {
        self.note(&e);
        if !stmt::is_stale(&e) {
            return Err(e.into());
        }
        stmt::clear_caches(&self.pool);
        if g.retried || !g.first || self.started.load(Ordering::SeqCst) != 1 {
            tracing::warn!(error = %e, "stale cached statement inside a transaction (caches cleared)");
            return Err(e.into());
        }
        tracing::info!(error = %e, "stale cached statement: caches cleared, transaction restarted");
        g.retried = true;
        self.client()?.batch_execute("rollback; begin").await?;
        Ok(())
    }

    /// Runs one statement; the number of rows it affected.
    ///
    /// # Errors
    /// When the statement fails, or [`Error::TransactionControl`] for `begin`, `commit` and the like (savepoints are
    /// fine).
    pub async fn execute(&self, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Result<u64, Error> {
        let mut g = self.guard(sql)?;
        statement!(self, g, sql, params, execute)
    }

    /// Runs one query; every row.
    ///
    /// # Errors
    /// When the query fails.
    pub async fn query(&self, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Result<Vec<Row>, Error> {
        let mut g = self.guard(sql)?;
        statement!(self, g, sql, params, query)
    }

    /// Runs one query that returns exactly one row.
    ///
    /// # Errors
    /// When the query fails or does not return exactly one row.
    pub async fn query_one(&self, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Result<Row, Error> {
        let mut g = self.guard(sql)?;
        statement!(self, g, sql, params, query_one)
    }

    /// Runs one query that returns at most one row.
    ///
    /// # Errors
    /// When the query fails or returns more than one row.
    pub async fn query_opt(&self, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Result<Option<Row>, Error> {
        let mut g = self.guard(sql)?;
        statement!(self, g, sql, params, query_opt)
    }

    /// Runs statements without parameters (the simple query protocol).
    ///
    /// # Errors
    /// When a statement fails, or [`Error::TransactionControl`] when one is `begin`, `commit` or the like.
    pub async fn batch_execute(&self, sql: &str) -> Result<(), Error> {
        let g = self.guard(sql)?;
        if let Err(e) = self.client()?.batch_execute(sql).await {
            self.note(&e);
            return Err(e.into());
        }
        g.ok(Ok(()))
    }

    /// `pg_notify(channel, payload)`, delivered to listeners when the transaction commits.
    ///
    /// # Errors
    /// When the statement fails.
    pub async fn notify(&self, channel: &str, payload: &str) -> Result<(), Error> {
        self.execute("select pg_notify($1, $2)", &[&channel, &payload]).await?;
        Ok(())
    }

    /// Ends the transaction (`commit` or `rollback`) and hands the connection back to the pool.
    async fn finish(mut self, sql: &str) -> Result<(), Error> {
        let res = self.client()?.batch_execute(sql).await;
        if res.is_ok() {
            // back to the pool only once the transaction is over; on failure Drop closes it
            drop(self.client.take());
        }
        Ok(res?)
    }

    /// Commits. When a statement failed or was cancelled, first asks the server whether the transaction is aborted
    /// (`COMMIT` of an aborted transaction rolls back and reports no error): then it rolls back and answers
    /// [`Error::RolledBack`].
    ///
    /// The error comes with whether the transaction may run again: the connection was lost before `COMMIT` was sent
    /// (nothing was committed). Once `COMMIT` is sent its outcome is unknown when the connection goes, so never.
    async fn commit(self) -> Result<(), (Error, bool)> {
        if self.doubt.load(Ordering::SeqCst) {
            let lost = self.lost.load(Ordering::SeqCst);
            match self.client().map_err(|e| (e, lost))?.simple_query("select 1").await {
                Ok(_) => {}
                Err(e) if e.code() == Some(&SqlState::IN_FAILED_SQL_TRANSACTION) => {
                    self.finish("rollback").await.map_err(|e| (e, false))?;
                    return Err((Error::RolledBack, lost));
                }
                // the connection is in an unknown state: Drop closes it
                Err(e) => {
                    let again = lost || crate::error::transient_db(&e);
                    return Err((e.into(), again));
                }
            }
        }
        self.finish("commit").await.map_err(|e| (e, false))
    }
}

/// Makes the closure's type higher-ranked over the borrow of the transaction (closures passed through a `let` are
/// not otherwise inferred that way). Used by [`tx!`](crate::tx!) only.
#[doc(hidden)]
pub fn __tx_fn<'env, T, E, F>(f: F) -> F
where
    F: for<'a> Fn(&'a Tx<'env>) -> TxFuture<'a, T, E>,
{
    f
}

/// Runs `f` in one transaction on a pooled connection: commits when it returns `Ok`, rolls back when it returns
/// `Err`; a panic or a dropped future closes the connection (the server rolls back). When the connection was lost
/// before `COMMIT` was sent (the database away for a moment, [`crate::retry`]), `f` runs again from the start on a new
/// connection, so it must only touch the database (the clippy rule above) and its captures are borrowed. Used by
/// [`tx!`](crate::tx!) only.
///
/// # Errors
/// `f`'s error, or [`Error`] (converted) when no connection could be had, `BEGIN` failed, `COMMIT` failed, or a
/// statement error left the transaction aborted though `f` returned `Ok` ([`Error::RolledBack`]).
#[doc(hidden)]
pub async fn __run_tx<'env, T, E, F>(pool: &Pool, f: F) -> Result<T, E>
where
    F: for<'a> Fn(&'a Tx<'env>) -> TxFuture<'a, T, E>,
    E: From<Error>,
{
    let mut patience = crate::retry::Patience::default();
    loop {
        let (res, again) = run_tx_once(pool, &f).await;
        match res {
            Err(e) if again && patience.again("transaction", &Error::Closed) => {
                drop(e);
                tokio::time::sleep(crate::retry::RETRY_GAP).await;
            }
            res => return res,
        }
    }
}

/// One try of [`__run_tx`]: its result, and whether it may run again (the connection was lost before `COMMIT`).
async fn run_tx_once<'env, T, E, F>(pool: &Pool, f: &F) -> (Result<T, E>, bool)
where
    F: for<'a> Fn(&'a Tx<'env>) -> TxFuture<'a, T, E>,
    E: From<Error>,
{
    let client = match crate::retry::get(pool.deadpool()).await {
        Ok(c) => c,
        Err(e) => return (Err(e.into()), false), // crate::retry::get waited already
    };
    // the Tx owns the connection before `begin` is sent: a future cancelled while `begin` is in flight (a timeout,
    // a select!, a dropped handler) closes the connection rather than handing it back with the BEGIN still queued
    let tx = Tx {
        client: Some(client),
        pool: pool.deadpool().clone(),
        started: AtomicU32::new(0),
        doubt: AtomicBool::new(false),
        lost: AtomicBool::new(false),
        _env: PhantomData,
    };
    let begun = match tx.client() {
        Ok(c) => c.batch_execute("begin").await,
        Err(e) => return (Err(e.into()), false),
    };
    if let Err(e) = begun {
        let again = crate::error::transient_db(&e);
        return (Err(Error::from(e).into()), again);
    }
    match f(&tx).await {
        Ok(v) => match tx.commit().await {
            Ok(()) => (Ok(v), false),
            Err((e, again)) => (Err(e.into()), again),
        },
        Err(e) => {
            let again = tx.lost.load(Ordering::SeqCst);
            if let Err(rb) = tx.finish("rollback").await
                && !again
            {
                tracing::warn!(error = %rb, "rollback failed (the connection is discarded)");
            }
            (Err(e), again)
        }
    }
}

/// Runs a closure in one transaction and evaluates to a future of its result: commit on `Ok`, rollback on `Err`.
///
/// ```ignore
/// let n: i64 = aviary_pg::tx!(&pool, |t| {
///     t.execute("insert into things (id) values ($1)", &[&id]).await?;
///     let row = t.query_one("select count(*) from things", &[]).await?;
///     Ok(row.get(0))
/// })
/// .await?;
///
/// // with the caller's own error type (it must implement `From<aviary_pg::Error>`)
/// let v = aviary_pg::tx!(&pool, |t| -> Result<u64, MyError> { Ok(t.execute("…", &[]).await?) }).await?;
/// ```
///
/// Inside the closure a network call is a clippy error (platform 4.3): finish the transaction, then call out.
#[macro_export]
macro_rules! tx {
    ($pool:expr, |$t:ident| -> $ret:ty $body:block) => {{
        // the one sanctioned use: clippy.toml disallows `__run_tx` everywhere else
        #[allow(clippy::disallowed_methods)]
        let __aviary_pg_run = $crate::__run_tx;
        #[deny(clippy::disallowed_methods)]
        let __aviary_pg_tx = $crate::__tx_fn(|$t| {
            ::std::boxed::Box::pin(async move {
                let __aviary_pg_out: $ret = $body;
                __aviary_pg_out
            })
        });
        __aviary_pg_run($pool, __aviary_pg_tx)
    }};
    ($pool:expr, |$t:ident| $body:expr) => {
        $crate::tx!($pool, |$t| -> ::std::result::Result<_, $crate::Error> { $body })
    };
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]

    use std::time::Duration;

    use deadpool_postgres::RecyclingMethod;

    /// A `tx!` cancelled at any point (while the pool hands out the connection, while `begin` is in flight, inside
    /// the closure) never leaves a pooled connection inside a transaction, even with no recycle check at all.
    #[tokio::test]
    async fn a_tx_cancelled_anywhere_never_hands_back_a_connection_inside_it() {
        let url = crate::testdb::url();
        let pool =
            crate::pool::connect_recycling(&url, "cancel-fast", 1, Duration::from_secs(15), RecyclingMethod::Fast)
                .unwrap();
        let other = crate::testdb::pool("cancel-fast-other", 1);
        let table = format!("cancel_{}", uuid::Uuid::new_v4().simple());
        other
            .get()
            .await
            .unwrap()
            .batch_execute(&format!("create table {table} (id int)"))
            .await
            .unwrap();
        // warm: one idle connection, so `get` resolves on the first poll and the cancellation lands in `begin`
        pool.get().await.unwrap().execute("select 1", &[]).await.unwrap();
        let insert = format!("insert into {table} values ($1)");
        let mut delays = vec![Duration::ZERO; 20];
        delays.extend((1..=40).map(|i| Duration::from_micros(i * 100)));
        for (i, delay) in delays.into_iter().enumerate() {
            let i = i32::try_from(i).unwrap();
            let _ = tokio::time::timeout(
                delay,
                crate::tx!(&pool, |t| {
                    t.execute("select pg_sleep(0.01)", &[]).await?;
                    Ok(())
                }),
            )
            .await;
            pool.get().await.unwrap().execute(&insert, &[&i]).await.unwrap();
            let seen: i64 = other
                .get()
                .await
                .unwrap()
                .query_one(&format!("select count(*) from {table} where id = $1"), &[&i])
                .await
                .unwrap()
                .get(0);
            assert_eq!(
                seen, 1,
                "round {i} (cancelled after {delay:?}): the next autocommit insert ran in a transaction"
            );
        }
        other
            .get()
            .await
            .unwrap()
            .batch_execute(&format!("drop table {table}"))
            .await
            .unwrap();
    }
}
